/**
 * =========================================================
 *  BBK – CLEAN BREADCRUMB (ULTIMATE FIX FOR ASTRA)
 *  ---------------------------------------------------------
 *  Pembersihan label dengan prioritas tinggi (999)
 * =========================================================
 */

// Hook untuk Yoast SEO
add_filter( 'wpseo_breadcrumb_links', 'bbk_ultimate_clean_breadcrumb', 999 );

// Hook untuk Astra Theme (Internal)
add_filter( 'astra_breadcrumb_trail_links', 'bbk_ultimate_clean_breadcrumb', 999 );

function bbk_ultimate_clean_breadcrumb( $links ) {
    if ( empty( $links ) || ! is_array( $links ) ) {
        return $links;
    }

    $prefix = 'Jual Barang Bekas Restoran';
    $archive_slug = '/jual-barang-bekas-restoran/';

    foreach ( $links as $key => $link ) {
        // Deteksi key teks: Yoast pakai 'text', Astra pakai 'label'
        $text_key = isset( $link['text'] ) ? 'text' : ( isset( $link['label'] ) ? 'label' : '' );
        
        if ( ! $text_key ) continue;

        $current_text = $link[$text_key];
        $current_url  = isset( $link['url'] ) ? $link['url'] : '';

        // 1. Cek jika ini adalah halaman Arsip Utama (Jabodetabek)
        if ( ! empty( $current_url ) && trailingslashit( $current_url ) === home_url( $archive_slug ) ) {
            $links[$key][$text_key] = 'JABODETABEK';
            continue; 
        }

        // 2. Bersihkan Prefix
        // Menggunakan str_ireplace agar lebih ringan dan tidak case-sensitive
        $cleaned = str_ireplace( $prefix, '', $current_text );

        // 3. Bersihkan kata sambung "di" (Misal: "di Serpong" -> "Serpong")
        $cleaned = preg_replace( '/^\s*di\s+/i', '', $cleaned );

        // 4. Ubah ke Uppercase dan masukkan kembali ke array
        $links[$key][$text_key] = mb_strtoupper( trim( $cleaned ) );
    }

    return $links;
}

