add_action('init', 'bbk_handle_status_update');

function bbk_handle_status_update() {
    if (!current_user_can('administrator')) {
        return;
    }

    if (!isset($_GET['bbk_update_status']) || !isset($_GET['product_id'])) {
        return;
    }

    $status = sanitize_text_field($_GET['bbk_update_status']);
    $product_id = intval($_GET['product_id']);

    // ===== UPDATE ACF =====
    update_field('status_unit', $status, $product_id);

    $timestamp_terjual = '';
    $stock_status = 'instock'; 

    if ($status === 'SOLD') {
        $timezone = new DateTimeZone('Asia/Jakarta');
        $tanggal_terjual = new DateTime('now', $timezone);
        $timestamp_terjual = $tanggal_terjual->format('Y-m-d H:i:s');
        $stock_status = 'outofstock';
    } 
    elseif ($status === 'DP') {
        $stock_status = 'onbackorder';
    }

    // ===== BYPASS UPDATE STOK WOOCOMMERCE =====
    update_post_meta($product_id, '_stock_status', $stock_status);
    wp_set_object_terms($product_id, $stock_status, 'product_visibility', false);

    // Simpan ke metadata lokal (hanya tanggal terjual)
    update_post_meta($product_id, '_tanggal_terjual', $timestamp_terjual);

    // ===== KIRIM KE GOOGLE SHEETS (BACKGROUND PROCESS) =====
    $web_app_url = 'https://script.google.com/macros/s/AKfycby7x_1Ityqekh8_nk3IsLJoFUGFm-avvp3rcYNJ4EXBq1MHle7Ma3Yph6paYoa3lEKL/exec'; 
    
    // Kita hapus parameter durasi_hari dari payload, Sheets yang urus via rumus Q2
    $body = array(
        'product_id'      => (string)$product_id, 
        'tanggal_terjual' => $timestamp_terjual
    );

    wp_remote_post($web_app_url, array(
        'method'      => 'POST',
        'timeout'     => 5,
        'redirection' => 5,
        'httpversion' => '1.0',
        'blocking'    => false, 
        'body'        => json_encode($body),
        'data_format' => 'body'
    ));

    // ===== PURGE LITESPEED =====
    if (class_exists('LiteSpeed_Cache_API')) {
        LiteSpeed_Cache_API::purge_url(get_permalink($product_id));
    }

    // Redirect via JS
    $target_url = get_permalink($product_id);
    echo '<script type="text/javascript">window.location.href="' . esc_url($target_url) . '";</script>';
    exit;
}

