function bbk_otomasi_tambah_produk($request) {
    if (!class_exists('WooCommerce')) {
        return new WP_REST_Response(['status' => 'error', 'message' => 'WooCommerce is not active'], 500);
    }

    $params = $request->get_json_params();
    $sku    = isset($params['sku']) ? sanitize_text_field($params['sku']) : '';

    if (empty($sku)) {
        return new WP_REST_Response(['status' => 'error', 'message' => 'SKU wajib diisi'], 400);
    }

    // UPSERT: UPDATE JIKA SKU ADA / CREATE BARU JIKA BELUM
    $existing_id = wc_get_product_id_by_sku($sku);

    if ($existing_id) {
        $product = wc_get_product($existing_id);
    } else {
        $product = new WC_Product_Simple();
    }
    
    // Setup Dasar Produk
    $product->set_name($params['title']);
    $product->set_status('publish');
    $product->set_description($params['content']);
    $product->set_short_description($params['excerpt']);
    $product->set_sku($sku);
    $product->set_stock_status($params['stock_status']);

    // =========================================================================
    // [TANDA: PENANGANAN KATEGORI WOOCOMMERCE]
    // Menghubungkan slug kategori dari Google Sheets ke Taksonomi WooCommerce
    // =========================================================================
    if (!empty($params['category_slug'])) {
        $term = get_term_by('slug', $params['category_slug'], 'product_cat');
        if ($term) {
            $product->set_category_ids([$term->term_id]);
        }
    }
    
    // Simpan produk pertama kali untuk mendapatkan Product ID
    $product_id = $product->save();
    
    // ===== SINKRONISASI FIELD ACF =====
    if (function_exists('update_field')) {
        update_field('kode_unit', $sku, $product_id);
        update_field('status_unit', $params['status_unit'], $product_id);
        update_field('lokasi_unit', $params['lokasi_unit'], $product_id);
        update_field('link_telegram', $params['link_telegram'], $product_id);
        update_field('kondisi_unit', $params['kondisi_unit'], $product_id);

        // 4 Field Harga ACF Baru
        update_field('harga_modal', $params['harga_modal'], $product_id);
        update_field('harga_buka_wa', $params['harga_buka_wa'], $product_id);
        update_field('harga_deal_wa', $params['harga_deal_wa'], $product_id);
        update_field('harga_floor_wa', $params['harga_floor_wa'], $product_id);

        // =========================================================================
        // [TANDA: TAMBAH FIELD ACF BARU DI SINI DI MASA DEPAN]
        // Contoh jika nanti tambah field ACF 'garansi_unit':
        // update_field('garansi_unit', $params['garansi_unit'], $product_id);
        // =========================================================================
    } else {
        // Fallback jika plugin ACF tidak aktif
        update_post_meta($product_id, 'kode_unit', $sku);
        update_post_meta($product_id, 'status_unit', $params['status_unit']);
        update_post_meta($product_id, 'lokasi_unit', $params['lokasi_unit']);
        update_post_meta($product_id, 'link_telegram', $params['link_telegram']);
        update_post_meta($product_id, 'kondisi_unit', $params['kondisi_unit']);

        update_post_meta($product_id, 'harga_modal', $params['harga_modal']);
        update_post_meta($product_id, 'harga_buka_wa', $params['harga_buka_wa']);
        update_post_meta($product_id, 'harga_deal_wa', $params['harga_deal_wa']);
        update_post_meta($product_id, 'harga_floor_wa', $params['harga_floor_wa']);

        // [TANDA: FALLBACK FIELD BARU DI SINI]
        // update_post_meta($product_id, 'garansi_unit', $params['garansi_unit']);
    }
    
    // Sinkronisasi Yoast SEO
    if (!empty($params['seo_title'])) {
        update_post_meta($product_id, '_yoast_wpseo_title', $params['seo_title']);
    }
    if (!empty($params['yoast_keyword'])) {
        update_post_meta($product_id, '_yoast_wpseo_focuskw', $params['yoast_keyword']);
    }
    if (!empty($params['yoast_description'])) {
        update_post_meta($product_id, '_yoast_wpseo_metadesc', $params['yoast_description']);
    }
    
    require_once(ABSPATH . 'wp-admin/includes/image.php');
    require_once(ABSPATH . 'wp-admin/includes/media.php');

    // 1. Gambar Utama
    if (!empty($params['main_image'])) {
        $response = wp_remote_get($params['main_image'], ['timeout' => 60]);
        if (!is_wp_error($response) && wp_remote_retrieve_response_code($response) === 200) {
            $filename   = sanitize_title($params['title']) . '-main-' . uniqid() . '.webp';
            $upload_dir = wp_upload_dir();
            $file       = $upload_dir['path'] . '/' . $filename;
            
            file_put_contents($file, wp_remote_retrieve_body($response));
            
            $attach_id = wp_insert_attachment([
                'post_mime_type' => 'image/webp', 
                'post_title'     => $filename, 
                'post_status'    => 'inherit'
            ], $file, $product_id);
            
            wp_update_attachment_metadata($attach_id, wp_generate_attachment_metadata($attach_id, $file));
            $product->set_image_id($attach_id);
        }
    }

    // 2. Galeri Foto
    if (!empty($params['photo_urls'])) {
        $gallery_ids = array();
        $urls        = preg_split('/[\s,]+/', $params['photo_urls']);
        
        foreach ($urls as $url) {
            if (empty($url)) continue;
            
            $res = wp_remote_get($url, ['timeout' => 45]);
            if (!is_wp_error($res) && wp_remote_retrieve_response_code($res) === 200) {
                $fname = sanitize_title($params['title']) . '-gal-' . uniqid() . '.webp';
                $path  = wp_upload_dir()['path'] . '/' . $fname;
                
                file_put_contents($path, wp_remote_retrieve_body($res));
                
                $aid = wp_insert_attachment([
                    'post_mime_type' => 'image/webp', 
                    'post_title'     => $fname, 
                    'post_status'    => 'inherit'
                ], $path, $product_id);
                
                wp_update_attachment_metadata($aid, wp_generate_attachment_metadata($aid, $path));
                $gallery_ids[] = $aid;
            }
        }
        if (!empty($gallery_ids)) {
            $product->set_gallery_image_ids($gallery_ids);
        }
    }
    
    // Simpan ulang produk
    $product->save();
    
    return new WP_REST_Response(['id' => $product_id, 'status' => 'success'], 200);
}

add_filter( 'posts_orderby', 'bbk_advanced_catalog_ordering', 9999, 2 );

function bbk_advanced_catalog_ordering( $orderby, $query ) {
    // Jalankan hanya di halaman toko (Shop), Kategori, dan Tag di front-end
    if ( ! is_admin() && $query->is_main_query() && ( is_shop() || is_product_category() || is_product_tag() ) ) {
        global $wpdb;

        // 1. Kelompokkan status stok: instock duluan (1), outofstock belakangan (2)
        // 2. Jika instock: urutkan berdasarkan tanggal TERBARU ke terlama (DESC)
        // 3. Jika outofstock (SOLD): urutkan berdasarkan tanggal TERLAMA ke terbaru (ASC)
        $orderby = " 
            CASE 
                WHEN {$wpdb->postmeta}.meta_value = 'instock' THEN 1 
                WHEN {$wpdb->postmeta}.meta_value = 'outofstock' THEN 2 
                ELSE 3 
            END ASC,
            CASE 
                WHEN {$wpdb->postmeta}.meta_value = 'instock' THEN {$wpdb->posts}.post_date 
            END DESC,
            CASE 
                WHEN {$wpdb->postmeta}.meta_value = 'outofstock' THEN {$wpdb->posts}.post_date 
            END ASC
        ";
    }
    return $orderby;
}

