function bbk_bulk_get_permalinks($request) {
    $params = $request->get_json_params();
    $ids = isset($params['product_ids']) ? (array)$params['product_ids'] : [];
    
    $results = [];
    foreach ($ids as $id) {
        $product_id = intval($id);
        if ($product_id > 0) {
            $permalink = get_permalink($product_id);
            // Bersihkan jika ada domain origin
            $permalink = str_replace('origin.bukanbarukitchen.com', 'www.bukanbarukitchen.com', $permalink);
            $results[$product_id] = $permalink;
        }
    }
    
    return new WP_REST_Response(['permalinks' => $results], 200);
}

